pub fn insert(&self, key: Key, new_val: Value) -> (success: bool)
    atomically (au) {
        type InsertPred,
        (mpt: MPointsTo) -> (new_mpt: Commit<MPointsTo>),
        requires
            key == mpt.key(),
            self.id() == mpt.instance_id(),
        ensures
            new_mpt@.instance_id() == mpt.instance_id(),
            new_mpt@.key() == mpt.key(),
            new_mpt@.value() === Some(new_val) || new_mpt@.value() == mpt.value()

